# Parallel scheduling for `pytest -n N --dist loadgroup` (see README).
# Modules stay together so their expensive STEP fixtures load once per run;
# modules whose cost is in long independent tests are split per test; the
# synthetic-run users share one worker so the session fixture renders once.
# Heaviest groups are queued first to shorten the tail. Sequential runs are
# untouched: this applies only inside xdist worker processes.
_SYNTHETIC_RUN_MODULES = {
    "test_calibrate", "test_calibration_demo", "test_detect_aprilgrid", "test_mujoco_calibration",
}
_SPLIT_PER_TEST = (
    "test_pg3_guide_relief", "test_pg3_pivot_motion", "test_pg3_crank_representation",
    "test_pg3_bench_cluster", "test_pg3",
)


@pytest.hookimpl(tryfirst=True)
def pytest_collection_modifyitems(config, items):
    if "PYTEST_XDIST_WORKER" not in os.environ:
        return
    order = {name: i for i, name in enumerate(_SPLIT_PER_TEST)}
    order["synthetic_run"] = len(order)

    def group(item):
        module = item.module.__name__.rsplit(".", 1)[-1]
        if module in _SYNTHETIC_RUN_MODULES:
            return "synthetic_run", "synthetic_run"
        if module in _SPLIT_PER_TEST:
            return module, item.nodeid
        return module, module

    ranked = []
    for index, item in enumerate(items):
        family, name = group(item)
        if not item.get_closest_marker("xdist_group"):
            item.add_marker(pytest.mark.xdist_group(name))
        ranked.append((order.get(family, len(order) + 1), index, item))
    items[:] = [item for _, _, item in sorted(ranked, key=lambda r: r[:2])]

