    uses_read_step = re.search(r'\bread_step\(', s2) is not None
    def fix_import(m):
        names = [x.strip() for x in m.group(1).split(',')]
        if 'read_rows' not in names: names.append('read_rows')
        if not uses_read_step and 'read_step' in names: names.remove('read_step')
        return 'from scripts.assembly_io import ' + ', '.join(sorted(names))
