import sys, re
sys.path.insert(0, ".")
import numpy as np, cadquery as cq
from OCP.BRepAlgoAPI import BRepAlgoAPI_Common
from scripts.step_cache import read_rows
from scripts.survey_arm_fastener_sites import concave_bores, coaxial
from scripts.assembly_io import bounds
shapes = {r.name: r.world for r in read_rows("outputs/camera-mount-id5-overhead-d405-r5/CAD/ID5_D405_mid_ASSEMBLY.step")}
servo = {}
for n, s in shapes.items():
    m = re.match(r"ARM_(M0\d)_ref", n)
    if m: servo.setdefault(m.group(1), []).extend(concave_bores(s, 0.8, 1.7))
def material_along(shape, p, d, half=40.0):
    # thin cylinder (r=0.05) along the axis; its common with the part gives material intervals
    probe = cq.Solid.makeCylinder(0.05, 2 * half, cq.Vector(*(p - d * half)), cq.Vector(*d))
    common = shape.intersect(probe)
    ivs = []
    for sol in common.Solids():
        b = bounds(sol); lo, hi = sorted([np.array(b[:3]) @ d, np.array(b[3:]) @ d])
        ivs.append((round(lo, 2), round(hi, 2), round(hi - lo, 2)))
    return sorted(ivs)
for link, target in (("ARM_P01_base", "M01"), ("ARM_P02_yaw_carrier", "M01"), ("ARM_P02_yaw_carrier", "M02")):
    ls = shapes[link]
    print(f"== {link} -> {target}")
    for b in concave_bores(ls, 0.8, 3.5):
        if any(coaxial(b, m) for m in servo[target]):
            # annulus just outside the bore radius: material the screw head/washer bears on
            off = np.cross(b["dir"], [1, 0, 0] if abs(b["dir"][0]) < 0.9 else [0, 1, 0]); off /= np.linalg.norm(off)
            p_ring = b["point"] + off * (b["radius"] + 0.6)
            print(f"   bore d{2*b['radius']:.2f} axis {np.round(b['dir'],2)} at {np.round(b['point'],1)}: material beside bore (along axis) {material_along(ls, p_ring, b['dir'])}")
